#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BTargetLifecycleTests {
  internal static JObject Packet(string name="initial-same-run")=>(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CommanderS1-20260922/combat-b-target-lifecycle-traces-20261003.json"))["traces"].Single(t=>(string)t["name"]==name)["response"].DeepClone();
  static object Read(JObject packet,string hash){var type=typeof(BDirectAttackBasicLoop).Assembly.GetType("LastRail.Battle.BTargetLifecycleJournal");Assert.NotNull(type,"Verified immutable lifecycle journal is missing");try{return type.GetMethod("Read",BindingFlags.Public|BindingFlags.Static).Invoke(null,new object[]{packet,Packet()["originalSource"],hash});}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
  [Test] public void SupplierJournalIsVerifiedAgainstIndependentTrustAndOriginalRoot(){var p=Packet("same-run-new-generation");Assert.NotNull(Read(p,(string)p["packetHash"]));}
  [Test] public void WrongIndependentHashRejectsOtherwiseValidEnvelope(){var p=Packet();Assert.Throws<ArgumentException>(()=>Read(p,"sha256:"+new string('0',64)));}
  [Test] public void RehashedReceiptTamperCannotBecomeTrustedJournal(){var p=Packet("same-run-new-generation");p["snapshot"]["receipts"][0]["receipt"]["originalTick"]=351;Assert.Throws<ArgumentException>(()=>Read(p,(string)p["packetHash"]));}
  static object Invoke(object owner,string method,params object[] args){var type=owner as Type??owner.GetType();var m=type.GetMethod(method);Assert.NotNull(m,"Missing native lifetime boundary: "+method);try{return m.Invoke(owner is Type?null:owner,args);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
  internal static BDirectAttackBasicLoop Fresh(){var p=Packet();return (BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"CreateLifecycleValidation",p,(string)p["packetHash"],BMiraActiveExecutionTests.Definitions(),10000);}
  // Unit-only supplier projection. The separate authenticated supervisor must exercise the real producer.
  internal static JObject Project(JObject prior,JObject input){var p=(JObject)prior.DeepClone();var current=(JObject)input["previous"].DeepClone();long revision=(long)input["expectedRevision"]+1;current["generation"]="LOCAL_LIFECYCLE:"+BDirectAttackInput.Digest(new JObject{["rootPacketHash"]=input["rootPacketHash"].DeepClone(),["contextId"]=input["contextId"].DeepClone(),["eventId"]=input["eventId"].DeepClone(),["revision"]=revision}).Substring(7);var body=new JObject{["version"]=input["version"].DeepClone(),["eventId"]=input["eventId"].DeepClone(),["rootPacketHash"]=input["rootPacketHash"].DeepClone(),["contextId"]=input["contextId"].DeepClone(),["revision"]=revision,["originalTick"]=input["originalTick"].DeepClone(),["originalSequence"]=input["originalSequence"].DeepClone(),["previous"]=input["previous"].DeepClone(),["current"]=current,["resetProfileHash"]=input["resetProfileHash"].DeepClone(),["previousJournalHash"]=p["journalHash"].DeepClone(),["runtimeReset"]=false};body["receiptHash"]=BDirectAttackInput.Digest(new JObject{["input"]=input.DeepClone(),["receipt"]=body.DeepClone()});((JArray)p["snapshot"]["receipts"]).Add(new JObject{["input"]=input.DeepClone(),["receipt"]=body});foreach(var name in new[]{"revision","currentTarget","journalHash"}){var value=name=="revision"?(JToken)new JValue(revision):name=="currentTarget"?current:body["receiptHash"];p[name]=value.DeepClone();p["snapshot"][name]=value.DeepClone();}p.Remove("packetHash");p["packetHash"]=BDirectAttackInput.Digest(p);return p;}
  internal static JObject Prepare(BDirectAttackBasicLoop s,string id)=>(JObject)Invoke(s,"PrepareTargetLifetime",id);
  internal static void Apply(BDirectAttackBasicLoop s,JObject p,JObject input)=>Invoke(s,"RecordTargetLifetime",input,p,(string)p["packetHash"]);
  [Test] public void NativeReplacementMissesOldShotPreservesReadyAndUsesNewGenerationAtReady(){var s=Fresh();s.SetActiveAuto("off",false);s.RequestActive("old");s.Advance("emit",3000000,300);var input=Prepare(s,"replace");Assert.AreEqual(300,(long)input["originalTick"]);Assert.Greater((long)input["originalSequence"],8);var p=Project(Packet(),input);Apply(s,p,input);Assert.AreEqual(700,s.Hp("enemy"));Assert.AreEqual(9260,(long)s.Capture()["active"]["readyTick"]);s.Advance("old-impact",1200000,120);Assert.AreEqual("RESOLVED_MISS",(string)s.Capture()["active"]["shots"][0]["status"]);s.Advance("ready-minus-one",88390000,8839);Assert.AreEqual("REJECTED_COOLDOWN",(string)s.RequestActive("early")["requestStatus"]);s.Advance("ready",10000,1);Assert.AreEqual("ACCEPTED",(string)s.RequestActive("new")["requestStatus"]);Assert.IsTrue(JToken.DeepEquals(p["currentTarget"],s.Capture()["active"]["lockedTarget"]));s.Advance("new-burst",14200000,1420);Assert.IsTrue(((JArray)s.Capture()["active"]["shots"]).All(x=>(string)x["status"]=="RESOLVED_HIT"));}
  [Test] public void InvalidLifetimeKeepsEntireNativeCaptureUnchanged(){var s=Fresh();var input=Prepare(s,"replace");var p=Project(Packet(),input);input["originalSequence"]=100;var before=s.Capture();Assert.Throws<ArgumentException>(()=>Apply(s,p,input));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void FullLifecycleRestoreReplaysSameLifetimeAndOldShotWithoutNewRun(){var s=Fresh();s.RequestActive("cast");s.Advance("emit",3000000,300);var input=Prepare(s,"replace");var p=Project(Packet(),input);Apply(s,p,input);var cache=s.Capture();var restored=(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"RestoreLifecycleValidation",cache,p,(string)p["packetHash"],BMiraActiveExecutionTests.Definitions(),10000);Assert.IsTrue(JToken.DeepEquals(cache,restored.Capture()));s.Advance("tail",11200000,1120);restored.Advance("tail",11200000,1120);Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));}
  [Test] public void LifecycleTransportExistsForAuthenticatedIndependentHashRead(){Assert.NotNull(typeof(BDirectAttackBasicLoop).Assembly.GetType("LastRail.Battle.BTargetLifecycleHttpTransport"),"Missing actual authenticated lifecycle exchange");}
  static string Rehash(JObject p){p.Remove("packetHash");var hash=BDirectAttackInput.Digest(p);p["packetHash"]=hash;return hash;}
  [TestCase("missing")][TestCase("receipt")][TestCase("order")][TestCase("profile")][TestCase("root")][TestCase("capacity")]
  public void CorruptTrustedEnvelopeCannotPartiallyPublishNativeLifetime(string change){var s=Fresh();s.RequestActive("cast");s.Advance("flight",3000000,300);var input=Prepare(s,"replace");var p=Project(Packet(),input);var before=s.Capture();
   if(change=="missing")((JArray)p["snapshot"]["receipts"]).Clear();
   else if(change=="receipt")p["snapshot"]["receipts"][0]["receipt"]["receiptHash"]="sha256:"+new string('0',64);
   else if(change=="order"){var next=(JObject)input.DeepClone();next["eventId"]="second";next["expectedRevision"]=1;next["previous"]=p["currentTarget"].DeepClone();p=Project(p,next);}
   else if(change=="profile")p["resetProfile"]["statusPolicy"]="COPY_PREVIOUS";
   else if(change=="root")p["rootPacketHash"]="sha256:"+new string('0',64);
   else {var rows=(JArray)p["snapshot"]["receipts"];while(rows.Count<1025)rows.Add(rows[0].DeepClone());}
   string hash=Rehash(p);Assert.Throws<ArgumentException>(()=>s.RecordTargetLifetime(input,p,hash));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));
  }
  [Test] public void DuplicateReplayPreservesOriginalResultAndChangedBodyIsRejected(){var s=Fresh();var input=Prepare(s,"replace");var p=Project(Packet(),input);var result=s.RecordTargetLifetime(input,p,(string)p["packetHash"]);var before=s.Capture();Assert.AreSame(result,s.RecordTargetLifetime(input,p,(string)p["packetHash"]));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));var changed=(JObject)input.DeepClone();changed["originalTick"]=1;Assert.Throws<ArgumentException>(()=>Apply(s,p,changed));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void StaleNativePreparationAfterClockAdvanceRejectsWithoutPublication(){var s=Fresh();var input=Prepare(s,"replace");var p=Project(Packet(),input);s.Advance("clock",10000,1);var before=s.Capture();Assert.Throws<ArgumentException>(()=>Apply(s,p,input));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void CommandCapacityFailurePreservesHpClockAndLifecycleTogether(){var p=Packet();var s=(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"CreateLifecycleValidation",p,(string)p["packetHash"],BMiraActiveExecutionTests.Definitions(),1);s.SetActiveAuto("off",false);var input=Prepare(s,"replace");p=Project(p,input);var before=s.Capture();Assert.Throws<ArgumentException>(()=>Apply(s,p,input));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void CallerGenerationObservationCannotBypassVerifiedLifetime(){var s=Fresh();var identity=(JObject)Packet()["currentTarget"].DeepClone();identity["generation"]="caller-arbitrary";var before=s.Capture();Assert.Throws<ArgumentException>(()=>s.ApplyOriginalActiveObservation(new JObject{["kind"]="LOCAL_ORIGINAL",["eventId"]="bypass",["operation"]="TARGET",["identity"]=identity,["present"]=true,["range"]=true}));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [TestCase("lifecycle")][TestCase("activeOwner")][TestCase("active")][TestCase("state")][TestCase("results")]
  public void FullRestoreRejectsTamperedCrossOwnerState(string area){var s=Fresh();s.RequestActive("cast");s.Advance("emit",3000000,300);var input=Prepare(s,"replace");var p=Project(Packet(),input);Apply(s,p,input);var cache=s.Capture();if(area=="results")cache[area][0]["tick"]=1;else cache[area]["unknown"]=1;var before=s.Capture();Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreLifecycleValidation(cache,p,(string)p["packetHash"],BMiraActiveExecutionTests.Definitions(),10000));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void LifetimeResetClearsPriorDefenseImmunityShieldButKeepsActorAndClockDebt(){var s=Fresh();s.RequestActive("cast");s.Advance("emit",3000000,300);s.SetSpeed("half",3);s.Advance("odd-debt",1,0);foreach(var kind in new[]{"IMMUNITY","DEFENSE","SHIELD"}){var o=new JObject{["kind"]="LOCAL_ORIGINAL",["eventId"]=kind,["operation"]=kind};if(kind=="IMMUNITY")o["value"]=true;else if(kind=="DEFENSE")o["value"]=new JObject{["numerator"]="50000",["denominator"]="1"};else{o["amount"]=100;o["expiry"]=20000;}s.ApplyOriginalActiveObservation(o);}var input=Prepare(s,"reset");var p=Project(Packet(),input);var prior=s.Capture();Apply(s,p,input);Assert.AreEqual(700,s.Hp("enemy"));Assert.IsTrue(JToken.DeepEquals(prior["state"]["direct"]["clock"],s.Capture()["state"]["direct"]["clock"]));Assert.AreEqual((long)prior["active"]["readyTick"],(long)s.Capture()["active"]["readyTick"]);var after=s.Capture();Assert.IsFalse((bool)after["state"]["direct"]["activeEntityState"]["immune"]);Assert.AreEqual("500",(string)after["state"]["direct"]["activeEntityState"]["defense"]["numerator"]);Assert.AreEqual(0,((JArray)after["state"]["direct"]["enemies"]["enemy"]["layers"]).Count);Assert.IsTrue(JToken.DeepEquals(prior["state"]["buffs"],after["state"]["buffs"]));Assert.IsTrue(JToken.DeepEquals(prior["state"]["direct"]["allies"],after["state"]["direct"]["allies"]));}
 }
}
